namespace Meridian.Infrastructure.Outbox;

/// <summary>
/// The first version's outbox adapter (AD-8): stores each message as an <see cref="OutboundMessage"/> row with status
/// <see cref="OutboundStatus.Simulated"/> so it can be shown on the job. No email or SMS is sent.
/// </summary>
internal sealed class SimulatedOutbox : IOutbox
{
    private readonly MeridianDbContext _db;

    public SimulatedOutbox(MeridianDbContext db)
    {
        _db = db;
    }

    public OutboundMessage Send(OutboundRequest request, DateTime nowUtc)
    {
        ArgumentNullException.ThrowIfNull(request);
        var outbound = OutboundMessage.Create(
            request.JobId,
            request.Channel,
            request.Recipient,
            request.TemplateId,
            request.Body,
            OutboundStatus.Simulated,
            nowUtc,
            request.MessageId);

        // Tracked only: written when the surrounding unit of work commits, with the job changes.
        _db.OutboundMessages.Add(outbound);
        return outbound;
    }

    public async Task<IReadOnlyList<OutboundMessage>> ListForJobAsync(Guid jobId, CancellationToken cancellationToken)
    {
        var messageIds = await _db.Jobs
            .Where(j => j.Id == jobId)
            .SelectMany(j => j.Messages.Select(m => (Guid?)m.Id))
            .ToListAsync(cancellationToken);
        return await _db.OutboundMessages
            .AsNoTracking()
            .Where(o => o.JobId == jobId || messageIds.Contains(o.MessageId))
            .OrderBy(o => o.CreatedAtUtc)
            .ThenBy(o => o.Id)
            .ToListAsync(cancellationToken);
    }

    public async Task<IReadOnlyList<OutboundMessage>> ListByTemplatesAsync(
        IReadOnlyCollection<string> templateIds,
        CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(templateIds);
        if (templateIds.Count == 0)
        {
            return Array.Empty<OutboundMessage>();
        }

        var ids = templateIds.ToList();
        return await _db.OutboundMessages
            .AsNoTracking()
            .Where(o => ids.Contains(o.TemplateId))
            .OrderByDescending(o => o.CreatedAtUtc)
            .ThenByDescending(o => o.Id)
            .ToListAsync(cancellationToken);
    }
}
namespace Meridian.Application.Templates;

/// <summary>
/// The fixed texts sent to staff when an emergency escalates (AD-7, R18, R19). Placeholders are the job reference,
/// the resolved address, the category and the fired emergency rules; model output and tenant text are never put in.
/// </summary>
public static class StaffTemplates
{
    public const string ReferencePlaceholder = "{reference}";
    public const string AddressPlaceholder = "{address}";
    public const string CategoryPlaceholder = "{category}";
    public const string RulesPlaceholder = "{rules}";

    /// <summary>Sent to the primary contact when an emergency arrives.</summary>
    public const string EscalationPrimaryId = "escalation-primary";

    /// <summary>Sent to the backup when the primary has not acknowledged in time.</summary>
    public const string EscalationBackupId = "escalation-backup";

    /// <summary>Shown for the address when the job's property is unresolved.</summary>
    public const string UnresolvedAddress = "address not resolved";

    /// <summary>Shown for the rules when none fired (the emergency came from the AI's proposal or a follow-up).</summary>
    public const string NoRules = "none";

    public const string EscalationPrimary =
        "EMERGENCY {reference}: {category} at {address}. Rules: {rules}. Please open the Meridian queue and acknowledge it.";

    public const string EscalationBackup =
        "EMERGENCY {reference} has not been acknowledged by the first contact: {category} at {address}. Rules: {rules}. You are the backup: please open the Meridian queue and acknowledge it.";

    /// <summary>Every staff template id, for listing staff notifications.</summary>
    public static readonly IReadOnlyList<string> Ids = new[] { EscalationPrimaryId, EscalationBackupId };

    public static string Text(string templateId) => templateId switch
    {
        EscalationPrimaryId => EscalationPrimary,
        EscalationBackupId => EscalationBackup,
        _ => throw new ArgumentOutOfRangeException(nameof(templateId), templateId, "Unknown staff template."),
    };

    /// <summary>Renders a staff template with only its four placeholders filled in.</summary>
    /// <param name="address">The resolved property name, or null when unresolved.</param>
    /// <param name="ruleIds">The fired emergency rule ids; empty when none fired.</param>
    public static string Render(string templateId, string reference, string? address, string category, IEnumerable<string> ruleIds)
    {
        if (string.IsNullOrWhiteSpace(reference))
        {
            throw new ArgumentException("A reference is required.", nameof(reference));
        }

        if (string.IsNullOrWhiteSpace(category))
        {
            throw new ArgumentException("A category is required.", nameof(category));
        }

        ArgumentNullException.ThrowIfNull(ruleIds);
        var rules = string.Join(", ", ruleIds);
        return Text(templateId)
            .Replace(ReferencePlaceholder, reference, StringComparison.Ordinal)
            .Replace(AddressPlaceholder, string.IsNullOrWhiteSpace(address) ? UnresolvedAddress : address, StringComparison.Ordinal)
            .Replace(CategoryPlaceholder, category, StringComparison.Ordinal)
            .Replace(RulesPlaceholder, rules.Length == 0 ? NoRules : rules, StringComparison.Ordinal);
    }
}
using Meridian.Domain.Rules;

namespace Meridian.Application.Templates;

/// <summary>
/// The fixed texts sent to tenants (AD-7, RULE-5, RULE-6). The only placeholder is <c>{reference}</c>, filled with the
/// job reference; model output, addresses and tenant text are never put into a tenant message.
/// </summary>
public static class TenantTemplates
{
    public const string ReferencePlaceholder = "{reference}";

    public const string AcknowledgementId = "acknowledgement";
    public const string GasSafetyId = "gas-safety";

    public const string Acknowledgement =
        "Thank you, we have received your maintenance report. Your reference is {reference}. If anything changes or gets worse, reply to this message quoting your reference. If you smell gas, call 0800 111 999 now.";

    /// <summary>The gas safety message (RULE-6). A constant: never reworded.</summary>
    public const string GasSafety =
        "If you can smell gas or your carbon monoxide alarm is sounding: leave the property now, do not use light switches or anything electrical, do not use flames, and call the National Gas Emergency line on 0800 111 999. Your report reference is {reference}. We have been told and will contact you.";

    /// <summary>The template text for <paramref name="templateId"/>.</summary>
    public static string Text(string templateId) => templateId switch
    {
        AcknowledgementId => Acknowledgement,
        GasSafetyId => GasSafety,
        _ => throw new ArgumentOutOfRangeException(nameof(templateId), templateId, "Unknown tenant template."),
    };

    /// <summary>Renders a template with only the job reference filled in.</summary>
    public static string Render(string templateId, string reference)
    {
        if (string.IsNullOrWhiteSpace(reference))
        {
            throw new ArgumentException("A reference is required.", nameof(reference));
        }

        return Text(templateId).Replace(ReferencePlaceholder, reference, StringComparison.Ordinal);
    }

    /// <summary>
    /// The acknowledgement template for a job: <see cref="GasSafetyId"/> when the gas or carbon-monoxide rule fired,
    /// otherwise <see cref="AcknowledgementId"/>.
    /// </summary>
    public static string AcknowledgementFor(IEnumerable<string> firedRuleIds)
    {
        ArgumentNullException.ThrowIfNull(firedRuleIds);
        return firedRuleIds.Any(id => id is EmergencyRuleIds.Gas or EmergencyRuleIds.CarbonMonoxide)
            ? GasSafetyId
            : AcknowledgementId;
    }
}
